test "test_rbp_binary_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    var msg = RbpBinary{
        .version = 1234,
        .flags = 1234,
        .msg_seq = 123456789,
        .ts_ns = 123456789,
        .body_len = 0,
        .checksum = 123456,
        .msg_type = 16,
        .body = .{ .new_order_req = .{ .req_id = 123456789, .channel_id = 1234, .adapter = 42, .account = "aaaaaaaaaaaaaaaa", .account_group = "aaaaaaaaaaaaaaaa", .cl_ord_id = "aaaaaaaaaaaaaaaa", .security_id = "aaaaaaaaaaaa", .market = 42, .side = 42, .price = -123456789, .order_qty = -123456789, .ord_type = 42, .time_in_force = 42, .pbu = "aaaaaaaa", .transact_time = 123456789, .ts_recv_ns = 123456789, .raw_ref = 123456789 } },
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try RbpBinary.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    msg.body_len = decoded.body_len;
    try std.testing.expect(msg.eql(decoded));
}
